import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.BdWD-ld-.js";const u=JSON.parse('{"title":"Agent Research and Competitive Intelligence · 2026-11-24","description":"","frontmatter":{"title":"Agent Research and Competitive Intelligence · 2026-11-24"},"headers":[],"relativePath":"en/runtime/daily-intelligence/2026-11-24.md","filePath":"en/runtime/daily-intelligence/2026-11-24.md","lastUpdated":1795487860000}'),o={name:"en/runtime/daily-intelligence/2026-11-24.md"};function i(s,e,l,p,d,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="agent-research-and-competitive-intelligence-·-2026-11-24" tabindex="-1">Agent Research and Competitive Intelligence · 2026-11-24 <a class="header-anchor" href="#agent-research-and-competitive-intelligence-·-2026-11-24" aria-label="Permalink to &quot;Agent Research and Competitive Intelligence · 2026-11-24&quot;">​</a></h1><p>Core finding: approval must reach execution boundaries; recovery must preserve authority and pending responsibility. SDK alpha.2 does not include every later merge; plugin signing retains unsigned compatibility.</p><p>27 selected observations, five analyses; zero new experiments/articles/formal development reviews. A separate Nov 23 experiment is reconciled under its actual date, not counted as today&#39;s testing. Report date Asia/Shanghai; event times UTC.</p><h2 id="carryover-reconciliation" tabindex="-1">Carryover reconciliation <a class="header-anchor" href="#carryover-reconciliation" aria-label="Permalink to &quot;Carryover reconciliation&quot;">​</a></h2><ul><li><strong>2026-11-19 A1</strong>：Retain November 19 scoped skill-boundary results; not rerun, live mounting/authority/execution remain pending.</li><li><strong>2026-11-19 A2</strong>：Pending: upstream/document checks only; original experiments not run.</li><li><strong>2026-11-19 A3</strong>：Partially complete: retain Nov 22 per-file requeue; a separate Nov 23 study ran three stop points three times (nine component trials), where queue labels did not distinguish underlying responsibility. Test adapter/temporary artifacts; real host, PM consumption, version binding and independent QA remain pending; not rerun today.</li><li><strong>2026-11-19 A4</strong>：Pending: upstream/document checks only; original experiments not run.</li><li><strong>2026-11-19 A5</strong>：Pending: upstream/document checks only; original experiments not run.</li><li><strong>2026-11-19 A6</strong>：Pending: upstream/document checks only; original experiments not run.</li><li><strong>2026-11-19 A7</strong>：Pending: upstream/document checks only; original experiments not run.</li><li><strong>2026-11-17 A2</strong>：Pending; retain historical stop regressions; external-effect/lost-receipt tests remain unrun.</li><li><strong>2026-11-17 A4</strong>：Partially complete via the same November 22 study as 2026-11-19 A3; do not count twice.</li><li><strong>2026-11-16 A1</strong>：Pending; real dual-host takeover unrun.</li><li><strong>2026-11-16 A2</strong>：Pending; real Core/ACP trials unrun.</li><li><strong>2026-11-22 A1</strong>：Pending; retry authority/resource/budget experiments unrun.</li><li><strong>2026-11-22 A2</strong>：Partially complete: retain Nov 22 per-file requeue; a separate Nov 23 study ran three stop points three times (nine component trials), where queue labels did not distinguish underlying responsibility. Test adapter/temporary artifacts; real host, PM consumption, version binding and independent QA remain pending; not rerun today.</li><li><strong>2026-11-22 A3</strong>：Pending; failed-governance-check and credential negative controls unrun.</li><li><strong>2026-11-22 A4</strong>：Document review advanced: Orca source MIT verified; product/isolation/hosted terms remain pending.</li><li><strong>2026-11-22 A5</strong>：Pending; install/migration/recovery/event/upgrade trials unrun.</li><li><strong>2026-11-23 A1</strong>：Pending; document updates do not replace the experiment.</li><li><strong>2026-11-23 A2</strong>：Partially complete: retain Nov 22 per-file requeue; a separate Nov 23 study ran three stop points three times (nine component trials), where queue labels did not distinguish underlying responsibility. Test adapter/temporary artifacts; real host, PM consumption, version binding and independent QA remain pending; not rerun today.</li><li><strong>2026-11-23 A3</strong>：Pending; document updates do not replace the experiment.</li><li><strong>2026-11-23 A4</strong>：Pending; document updates do not replace the experiment.</li><li><strong>2026-11-23 A5</strong>：Pending; document updates do not replace the experiment.</li><li><strong>2026-11-23 A6</strong>：Pending; document updates do not replace the experiment.</li></ul><p><a href="./../../research/2026-11-23-digital-employee-handoff-triage">Yesterday&#39;s nine controlled trials</a></p><p>Three stop points—undelivered, pending approval, result without report—three trials each. Real dispatch/approval storage/settlement with a test adapter; six approval/result cases shared a queue reason. This establishes component-label ambiguity, not prevalence or full UI/business acceptance.</p><h2 id="fact-observations" tabindex="-1">Fact observations <a class="header-anchor" href="#fact-observations" aria-label="Permalink to &quot;Fact observations&quot;">​</a></h2><h3 id="o1-·-move-approval-to-the-point-where-work-leaves-the-machine-the-guard-asks-before-git-push-gh-pr-create-merge-close-gh-release-changes-gh-repo-delete-package-publishes-and-dd-mkfs-shred-and-lets-commits-merges-rebases-resets-branch-and-tag-changes-and-recursive-deletes-run-agents-md-states-the-rule-with-an-ownership-limit-user-settings-json-keeps-six-ask-rules-and-bootstrap-passes-retire-withdrawn-so-merge-settings-py-removes-the-fifteen-withdrawn-rules-from-claude-settings-json-docs-readme-readme-zh-cn-guard-hook-faq-install-agents-md-skills-and-their-composer-copies-tests-the-paper-workflow-fixture-and-the-changelog-follow-vet-rounds-1-to-3-codex-and-agy-round-3-pass" tabindex="-1">O1 · Move approval to the point where work leaves the machine: the guard asks before git push, gh pr create/merge/close, gh release changes, gh repo delete, package publishes, and dd/mkfs/shred, and lets commits, merges, rebases, resets, branch and tag changes, and recursive deletes run; AGENTS.md states the rule with an ownership limit, user/settings.json keeps six ask rules, and bootstrap passes --retire-withdrawn so merge_settings.py removes the fifteen withdrawn rules from ~/.claude/settings.json. Docs (README, README.zh-CN, guard-hook, faq, install, agents-md), skills and their composer copies, tests, the paper-workflow fixture, and the CHANGELOG follow. /vet rounds 1 to 3 (Codex and Agy, round 3 PASS) <a class="header-anchor" href="#o1-·-move-approval-to-the-point-where-work-leaves-the-machine-the-guard-asks-before-git-push-gh-pr-create-merge-close-gh-release-changes-gh-repo-delete-package-publishes-and-dd-mkfs-shred-and-lets-commits-merges-rebases-resets-branch-and-tag-changes-and-recursive-deletes-run-agents-md-states-the-rule-with-an-ownership-limit-user-settings-json-keeps-six-ask-rules-and-bootstrap-passes-retire-withdrawn-so-merge-settings-py-removes-the-fifteen-withdrawn-rules-from-claude-settings-json-docs-readme-readme-zh-cn-guard-hook-faq-install-agents-md-skills-and-their-composer-copies-tests-the-paper-workflow-fixture-and-the-changelog-follow-vet-rounds-1-to-3-codex-and-agy-round-3-pass" aria-label="Permalink to &quot;O1 · Move approval to the point where work leaves the machine: the guard asks before git push, gh pr create/merge/close, gh release changes, gh repo delete, package publishes, and dd/mkfs/shred, and lets commits, merges, rebases, resets, branch and tag changes, and recursive deletes run; AGENTS.md states the rule with an ownership limit, user/settings.json keeps six ask rules, and bootstrap passes --retire-withdrawn so merge_settings.py removes the fifteen withdrawn rules from ~/.claude/settings.json. Docs (README, README.zh-CN, guard-hook, faq, install, agents-md), skills and their composer copies, tests, the paper-workflow fixture, and the CHANGELOG follow. /vet rounds 1 to 3 (Codex and Agy, round 3 PASS)&quot;">​</a></h3><p>yzhao062/anywhere-agents · 2026-11-23T02:34:10Z · <strong>COMMITTED</strong></p><p>Zhao moves approval to publication boundaries, allowing more local Git operations and recursive deletion under ownership limits; a personal harness policy, not an enterprise default.</p><p><a href="https://github.com/yzhao062/anywhere-agents/commit/2bc622bf8f50922cf489cf4fa27800d706f8370d" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o2-·-verify-signed-remote-plugin-archives-before-extraction-63489" tabindex="-1">O2 · Verify signed remote plugin archives before extraction (#63489) <a class="header-anchor" href="#o2-·-verify-signed-remote-plugin-archives-before-extraction-63489" aria-label="Permalink to &quot;O2 · Verify signed remote plugin archives before extraction (#63489)&quot;">​</a></h3><p>openai/codex · 2026-11-24T01:28:15Z · <strong>COMMITTED</strong></p><p>Verify signed remote plugin archives before extraction, while releases without signing metadata remain accepted; not mandatory universal signing.</p><p><a href="https://github.com/openai/codex/commit/e173e7b9b29a63f4a5b5171c1b9a610179bc38a2" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o3-·-support-encrypted-context-from-mcp-session-start-hooks-63474" tabindex="-1">O3 · Support encrypted context from MCP session-start hooks (#63474) <a class="header-anchor" href="#o3-·-support-encrypted-context-from-mcp-session-start-hooks-63474" aria-label="Permalink to &quot;O3 · Support encrypted context from MCP session-start hooks (#63474)&quot;">​</a></h3><p>openai/codex · 2026-11-24T00:13:03Z · <strong>COMMITTED</strong></p><p>Synchronous MCP SessionStart supports encrypted context capped at 40,000 bytes, excluding previews/plaintext spill; not arbitrary-log secrecy.</p><p><a href="https://github.com/openai/codex/commit/5b10c107ba06a0f0401da727819d813d267b3b01" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o4-·-add-gateway-enrollment-to-local-managed-requirements-63476" tabindex="-1">O4 · Add gateway enrollment to local managed requirements (#63476) <a class="header-anchor" href="#o4-·-add-gateway-enrollment-to-local-managed-requirements-63476" aria-label="Permalink to &quot;O4 · Add gateway enrollment to local managed requirements (#63476)&quot;">​</a></h3><p>openai/codex · 2026-11-24T00:14:14Z · <strong>COMMITTED</strong></p><p>Local requirements/MDM unify gateway and OAuth enrollment; MDM replaces as a unit, remote enrollment and conflicting routes are rejected.</p><p><a href="https://github.com/openai/codex/commit/8bb8ed6bab55d9f2b299e0abb1b9df6c3c383e66" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o5-·-fix-track-transient-instructions-and-gate-dynamic-instruction-routing" tabindex="-1">O5 · fix: track transient instructions and gate dynamic instruction routing <a class="header-anchor" href="#o5-·-fix-track-transient-instructions-and-gate-dynamic-instruction-routing" aria-label="Permalink to &quot;O5 · fix: track transient instructions and gate dynamic instruction routing&quot;">​</a></h3><p>google/adk-python · 2026-11-24T01:05:12Z · <strong>COMMITTED</strong></p><p>Transient tool instructions are tracked rather than replayed as persistent user input; live/some providers use system routing and plugins ignore transient content.</p><p><a href="https://github.com/google/adk-python/commit/9c22a89fe2d212a0672ea0bdfcc155ac8d361b5e" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o6-·-fix-acp-preserve-existing-session-when-resume-fails-5095" tabindex="-1">O6 · fix(acp): preserve existing session when resume fails (#5095) <a class="header-anchor" href="#o6-·-fix-acp-preserve-existing-session-when-resume-fails-5095" aria-label="Permalink to &quot;O6 · fix(acp): preserve existing session when resume fails (#5095)&quot;">​</a></h3><p>OpenHands/software-agent-sdk · 2026-11-23T16:20:32Z · <strong>COMMITTED</strong></p><p>Preserve existing ACP sessions when resume fails; real-host failover remains untested.</p><p><a href="https://github.com/OpenHands/software-agent-sdk/commit/077f3fad6d31cd852be5c87176e0a93c3b446126" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o7-·-fix-acp-tear-down-spawned-server-process-group-on-shutdown-posix-4909" tabindex="-1">O7 · fix(acp): tear down spawned server process group on shutdown (POSIX) (#4909) <a class="header-anchor" href="#o7-·-fix-acp-tear-down-spawned-server-process-group-on-shutdown-posix-4909" aria-label="Permalink to &quot;O7 · fix(acp): tear down spawned server process group on shutdown (POSIX) (#4909)&quot;">​</a></h3><p>OpenHands/software-agent-sdk · 2026-11-23T21:14:41Z · <strong>COMMITTED</strong></p><p>Tear down spawned ACP server process groups on shutdown on POSIX; do not infer Windows parity.</p><p><a href="https://github.com/OpenHands/software-agent-sdk/commit/0988e976491ff733bc09e976b36a271b0c511530" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o8-·-fix-sop-preserve-public-sop-ids-across-restarts-318" tabindex="-1">O8 · fix(sop): preserve public SOP IDs across restarts (#318) <a class="header-anchor" href="#o8-·-fix-sop-preserve-public-sop-ids-across-restarts-318" aria-label="Permalink to &quot;O8 · fix(sop): preserve public SOP IDs across restarts (#318)&quot;">​</a></h3><p>OpenBMB/StaffDeck · 2026-11-23T10:55:34Z · <strong>COMMITTED</strong></p><p>Preserve public SOP IDs across restart for workflow-reference continuity; not locally tested.</p><p><a href="https://github.com/OpenBMB/StaffDeck/commit/389d5d331cf40eb5f0aae83c4fa24f4ed10b0003" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o9-·-fix-macos-scope-runtime-signing-entitlements-313" tabindex="-1">O9 · fix(macos): scope runtime signing entitlements (#313) <a class="header-anchor" href="#o9-·-fix-macos-scope-runtime-signing-entitlements-313" aria-label="Permalink to &quot;O9 · fix(macos): scope runtime signing entitlements (#313)&quot;">​</a></h3><p>OpenBMB/StaffDeck · 2026-11-23T11:37:43Z · <strong>COMMITTED</strong></p><p>Scope macOS runtime signing entitlements, including Intel Node JIT; not a complete signing/upgrade validation.</p><p><a href="https://github.com/OpenBMB/StaffDeck/commit/685389d9bf00a791a3afb82070076ddd3ab38ebe" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o10-·-fix-orchestration-say-what-is-known-when-a-worker-goes-quiet-47947" tabindex="-1">O10 · fix(orchestration): say what is known when a worker goes quiet (#47947) <a class="header-anchor" href="#o10-·-fix-orchestration-say-what-is-known-when-a-worker-goes-quiet-47947" aria-label="Permalink to &quot;O10 · fix(orchestration): say what is known when a worker goes quiet (#47947)&quot;">​</a></h3><p>stablyai/orca · 2026-11-24T02:25:30Z · <strong>COMMITTED</strong></p><p>Ten minutes without hooks or screen change establishes no progress, not a slow-model diagnosis; quiet-worker notices reflect uncertainty.</p><p><a href="https://github.com/stablyai/orca/commit/06f0ca1a8bdc6be58350bb1ffb9825cdb75c2f95" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o11-·-feat-cloud-a-wake-not-ready-in-30-s-shows-could-not-start-with-try-again-10190" tabindex="-1">O11 · feat(cloud): a wake not ready in 30 s shows could-not-start with Try again (#10190) <a class="header-anchor" href="#o11-·-feat-cloud-a-wake-not-ready-in-30-s-shows-could-not-start-with-try-again-10190" aria-label="Permalink to &quot;O11 · feat(cloud): a wake not ready in 30 s shows could-not-start with Try again (#10190)&quot;">​</a></h3><p>superset-sh/superset · 2026-11-23T18:31:13Z · <strong>COMMITTED</strong></p><p>A cloud workspace not ready in 30 seconds shows could-not-start and Try again; a status change, not locally tested.</p><p><a href="https://github.com/ParadevAI/Paradev/commit/eac3ddf0e2fbdaf4b9866bb87172e58af92317b6" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o12-·-feat-billing-price-cloud-usage-at-the-customer-s-own-gb-hour-rates-10194" tabindex="-1">O12 · feat(billing): price cloud usage at the customer&#39;s own GB-hour rates (#10194) <a class="header-anchor" href="#o12-·-feat-billing-price-cloud-usage-at-the-customer-s-own-gb-hour-rates-10194" aria-label="Permalink to &quot;O12 · feat(billing): price cloud usage at the customer&#39;s own GB-hour rates (#10194)&quot;">​</a></h3><p>superset-sh/superset · 2026-11-23T18:33:11Z · <strong>COMMITTED</strong></p><p>Cloud usage uses customer-specific GB-hour rates; contract/old pricing comparison remains needed, with no local cost estimate.</p><p><a href="https://github.com/ParadevAI/Paradev/commit/92837386a7ed87968104b2e479b33fdb6390d363" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o13-·-stop-queued-function-tools-after-input-guardrail-rejection" tabindex="-1">O13 · Stop queued function tools after input guardrail rejection <a class="header-anchor" href="#o13-·-stop-queued-function-tools-after-input-guardrail-rejection" aria-label="Permalink to &quot;O13 · Stop queued function tools after input guardrail rejection&quot;">​</a></h3><p>openai/openai-agents-python · 2026-11-23T19:27:00Z · <strong>MERGED</strong> · main</p><p>Publish guardrail rejection promptly and stop queued tools at admission/invocation; nested rejection cancels/drains parent checks.</p><p><a href="https://github.com/openai/openai-agents-python/pull/6174" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o14-·-preserve-handoff-redaction-in-session-history" tabindex="-1">O14 · Preserve handoff redaction in Session history <a class="header-anchor" href="#o14-·-preserve-handoff-redaction-in-session-history" aria-label="Permalink to &quot;O14 · Preserve handoff redaction in Session history&quot;">​</a></h3><p>openai/openai-agents-python · 2026-11-23T19:18:00Z · <strong>MERGED</strong> · main</p><p>Persist filtered handoff arguments in Session history, matching original occurrences to avoid reused-call-ID mixups.</p><p><a href="https://github.com/openai/openai-agents-python/pull/6176" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o15-·-fix-sandbox-restrict-docker-storage-mount-privileges" tabindex="-1">O15 · fix(sandbox): restrict Docker storage mount privileges <a class="header-anchor" href="#o15-·-fix-sandbox-restrict-docker-storage-mount-privileges" aria-label="Permalink to &quot;O15 · fix(sandbox): restrict Docker storage mount privileges&quot;">​</a></h3><p>openai/openai-agents-python · 2026-11-24T02:29:57Z · <strong>MERGED</strong> · main</p><p>Reject in-container storage mounts on creation/resume and inspect privilege/added capabilities before reuse; trusted mount migration required.</p><p><a href="https://github.com/openai/openai-agents-python/pull/6189" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o16-·-fix-require-application-approval-for-local-images-in-codex-tool" tabindex="-1">O16 · fix: require application approval for local images in codex_tool <a class="header-anchor" href="#o16-·-fix-require-application-approval-for-local-images-in-codex-tool" aria-label="Permalink to &quot;O16 · fix: require application approval for local images in codex_tool&quot;">​</a></h3><p>openai/openai-agents-python · 2026-11-23T18:23:39Z · <strong>MERGED</strong> · main</p><p>Experimental codex_tool denies local images by default, requiring explicit app-managed aliases and checks before startup/resume.</p><p><a href="https://github.com/openai/openai-agents-python/pull/6171" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o17-·-check-realtime-output-guardrails-at-turn-completion" tabindex="-1">O17 · Check Realtime output guardrails at turn completion <a class="header-anchor" href="#o17-·-check-realtime-output-guardrails-at-turn-completion" aria-label="Permalink to &quot;O17 · Check Realtime output guardrails at turn completion&quot;">​</a></h3><p>openai/openai-agents-python · 2026-11-23T19:15:23Z · <strong>MERGED</strong> · main</p><p>Check Realtime output guardrails at turn completion; do not infer prior audio/text can be retracted.</p><p><a href="https://github.com/openai/openai-agents-python/pull/6178" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o18-·-apply-replay-checks-to-hosted-mcp-retries" tabindex="-1">O18 · Apply replay checks to hosted MCP retries <a class="header-anchor" href="#o18-·-apply-replay-checks-to-hosted-mcp-retries" aria-label="Permalink to &quot;O18 · Apply replay checks to hosted MCP retries&quot;">​</a></h3><p>openai/openai-agents-js · 2026-11-23T20:51:37Z · <strong>MERGED</strong> · main</p><p>Apply replay-safety checks to hosted MCP requests/approval responses; ambiguous outcomes must not be blindly retried like ordinary model calls.</p><p><a href="https://github.com/openai/openai-agents-js/pull/2711" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o19-·-fix-a2a-server-enforce-bearer-token-authentication-and-request-input-validation" tabindex="-1">O19 · fix(a2a-server): enforce bearer token authentication and request input validation <a class="header-anchor" href="#o19-·-fix-a2a-server-enforce-bearer-token-authentication-and-request-input-validation" aria-label="Permalink to &quot;O19 · fix(a2a-server): enforce bearer token authentication and request input validation&quot;">​</a></h3><p>google-gemini/gemini-cli · 2026-11-23T22:13:56Z · <strong>MERGED</strong> · main</p><p>A2A server enforces startup token, timing-safe equality and loopback Host/Origin; request isTrusted cannot grant workspace trust; restore stays within checkpoint directory.</p><p><a href="https://github.com/google-gemini/gemini-cli/pull/30420" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o20-·-fix-windows-extract-deep-harness-runtime-paths" tabindex="-1">O20 · fix(windows): extract deep Harness runtime paths <a class="header-anchor" href="#o20-·-fix-windows-extract-deep-harness-runtime-paths" aria-label="Permalink to &quot;O20 · fix(windows): extract deep Harness runtime paths&quot;">​</a></h3><p>OpenBMB/StaffDeck · 2026-11-23T11:10:27Z · <strong>MERGED</strong> · main</p><p>Windows deep-path extraction avoids registry changes; portable archive tests passed upstream, Windows package/first-run smoke still pending.</p><p><a href="https://github.com/OpenBMB/StaffDeck/pull/315" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o21-·-fix-channels-route-handoff-acknowledgements-by-channel" tabindex="-1">O21 · fix(channels): route handoff acknowledgements by channel <a class="header-anchor" href="#o21-·-fix-channels-route-handoff-acknowledgements-by-channel" aria-label="Permalink to &quot;O21 · fix(channels): route handoff acknowledgements by channel&quot;">​</a></h3><p>OpenBMB/StaffDeck · 2026-11-23T10:56:14Z · <strong>MERGED</strong> · main</p><p>Route handoff acknowledgements by resolved inbound channel, preserving private replies and avoiding repeated group text.</p><p><a href="https://github.com/OpenBMB/StaffDeck/pull/322" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o22-·-v1-0-0-alpha-2" tabindex="-1">O22 · v1.0.0-alpha.2 <a class="header-anchor" href="#o22-·-v1-0-0-alpha-2" aria-label="Permalink to &quot;O22 · v1.0.0-alpha.2&quot;">​</a></h3><p>openai/openai-agents-python · 2026-11-23T20:11:07Z · <strong>RELEASED_PRERELEASE</strong></p><p>Alpha.2 prerelease ships cross-worker sessions/approvals, hooks and redaction. New 1.24 snapshots are unreadable by alpha.1; upgrade readers first. Native recovery is limited to one direct command/edit approval, not terminated-command restart.</p><p><a href="https://github.com/openai/openai-agents-python/releases/tag/v1.0.0-alpha.2" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o23-·-v1-44-0" tabindex="-1">O23 · v1.44.0 <a class="header-anchor" href="#o23-·-v1-44-0" aria-label="Permalink to &quot;O23 · v1.44.0&quot;">​</a></h3><p>OpenHands/OpenHands · 2026-11-23T15:29:47Z · <strong>RELEASED</strong></p><p>Stable release includes automation visibility choices, flagged conversation mentions and budget errors; not installed.</p><p><a href="https://github.com/OpenHands/OpenHands/releases/tag/v1.44.0" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o24-·-v1-0-115-8" tabindex="-1">O24 · v1.0.115-8 <a class="header-anchor" href="#o24-·-v1-0-115-8" aria-label="Permalink to &quot;O24 · v1.0.115-8&quot;">​</a></h3><p>github/copilot-cli · 2026-11-23T19:10:51Z · <strong>RELEASED_PRERELEASE</strong></p><p>Release allows same-session identical-request approval reuse and review-model failover; equivalence/revocation conditions need testing.</p><p><a href="https://github.com/github/copilot-cli/releases/tag/v1.0.115-8" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o25-·-v2-1-331" tabindex="-1">O25 · v2.1.331 <a class="header-anchor" href="#o25-·-v2-1-331" aria-label="Permalink to &quot;O25 · v2.1.331&quot;">​</a></h3><p>anthropics/claude-code · 2026-11-23T21:34:41Z · <strong>RELEASED</strong></p><p>Release expands Code Mode platforms, gateway OIDC group parsing and doctor connectivity diagnostics; not proof of enterprise isolation.</p><p><a href="https://github.com/anthropics/claude-code/releases/tag/v2.1.331" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o26-·-v4-84-0" tabindex="-1">O26 · v4.84.0 <a class="header-anchor" href="#o26-·-v4-84-0" aria-label="Permalink to &quot;O26 · v4.84.0&quot;">​</a></h3><p>langfuse/langfuse · 2026-11-23T12:22:31Z · <strong>RELEASED</strong></p><p>Release adds MCP batch annotation queue tools and billable-events ledger migration; audit/billing records are not task acceptance.</p><p><a href="https://github.com/langfuse/langfuse/releases/tag/v4.84.0" target="_blank" rel="noreferrer">Primary evidence</a></p><h3 id="o27-·-昨日开放提案状态变化-proposal-status-transitions" tabindex="-1">O27 · 昨日开放提案状态变化 / Proposal status transitions <a class="header-anchor" href="#o27-·-昨日开放提案状态变化-proposal-status-transitions" aria-label="Permalink to &quot;O27 · 昨日开放提案状态变化 / Proposal status transitions&quot;">​</a></h3><p>openai/openai-agents-python · 2026-11-24T02:33:23Z · <strong>MIXED</strong></p><p>#6154 merged into experimental branch and alpha.2 supports redaction. #6124/#6131 merged after alpha.2 release and must not be claimed bundled. #6141/#6133/#6132 remain OPEN.</p><p><a href="https://github.com/openai/openai-agents-python/pull/6124" target="_blank" rel="noreferrer">Primary evidence</a> · <a href="https://github.com/openai/openai-agents-python/pull/6124" target="_blank" rel="noreferrer">PR 1</a> · <a href="https://github.com/openai/openai-agents-python/pull/6141" target="_blank" rel="noreferrer">PR 2</a> · <a href="https://github.com/openai/openai-agents-python/pull/6132" target="_blank" rel="noreferrer">PR 3</a> · <a href="https://github.com/openai/openai-agents-python/pull/6133" target="_blank" rel="noreferrer">PR 4</a> · <a href="https://github.com/openai/openai-agents-python/pull/6131" target="_blank" rel="noreferrer">PR 5</a> · <a href="https://github.com/openai/openai-agents-python/pull/6154" target="_blank" rel="noreferrer">PR 6</a></p><h2 id="research-analysis" tabindex="-1">Research analysis <a class="header-anchor" href="#research-analysis" aria-label="Permalink to &quot;Research analysis&quot;">​</a></h2><h3 id="a1-·-bind-approval-to-actions-and-effects" tabindex="-1">A1 · Bind approval to actions and effects <a class="header-anchor" href="#a1-·-bind-approval-to-actions-and-effects" aria-label="Permalink to &quot;A1 · Bind approval to actions and effects&quot;">​</a></h3><p>O1/O13/O15/O16/O18/O24</p><p>Zhao&#39;s personal policy emphasizes publication; SDK fixes enforce rejection, mounts and image grants. These are not interchangeable. Enterprise employees must also cover local sensitive data/deletion, not only machine exit. Post-approval identity/argument and queued-tool tests are unrun candidates.</p><h3 id="a2-·-supply-chain-verification-differs-from-confidentiality" tabindex="-1">A2 · Supply-chain verification differs from confidentiality <a class="header-anchor" href="#a2-·-supply-chain-verification-differs-from-confidentiality" aria-label="Permalink to &quot;A2 · Supply-chain verification differs from confidentiality&quot;">​</a></h3><p>O2/O3/O4/O5/O14/O27</p><p>Signatures do not prove trusted behavior; unsigned compatibility is not mandatory signing. Encrypted hooks do not cover arbitrary logs; history redaction differs from live output edits. FCoP can study evidence/artifact-digest relations; plugin verification and trace enforcement are runtime concerns. Zero new experiments.</p><h3 id="a3-·-recover-authority-state-and-pending-responsibility" tabindex="-1">A3 · Recover authority, state and pending responsibility <a class="header-anchor" href="#a3-·-recover-authority-state-and-pending-responsibility" aria-label="Permalink to &quot;A3 · Recover authority, state and pending responsibility&quot;">​</a></h3><p>O6/O7/O8/O11/O12/O18/O21/O22/O27</p><p>Alpha.2 needs upgraded readers, one writer and constrained native approvals; resume is not duplicate-effect safety. Yesterday&#39;s nine controlled runs shared queue labels despite different stops, requiring lower-level evidence for responsibility. This is not full-product defect prevalence. Carry 19A3/22A2/23A2; version binding/independent QA remain pending.</p><h3 id="a4-·-competitors-improve-workflow-and-desktop-delivery" tabindex="-1">A4 · Competitors improve workflow and desktop delivery <a class="header-anchor" href="#a4-·-competitors-improve-workflow-and-desktop-delivery" aria-label="Permalink to &quot;A4 · Competitors improve workflow and desktop delivery&quot;">​</a></h3><p>O8/O9/O10/O11/O12/O20/O21/O23/O24</p><p>StaffDeck main-radar learning value rises through SOP identity, channel receipts and packaging, but Windows first-run remains unverified. Paradev main radar adds wake/billing interest; Orca second circle adds evidence semantics. Keep mapping; commit volume does not establish maturity. Versioned installation/recovery/isolation trials remain unrun.</p><h3 id="a5-·-keep-diagnosis-and-acceptance-within-evidence" tabindex="-1">A5 · Keep diagnosis and acceptance within evidence <a class="header-anchor" href="#a5-·-keep-diagnosis-and-acceptance-within-evidence" aria-label="Permalink to &quot;A5 · Keep diagnosis and acceptance within evidence&quot;">​</a></h3><p>O5/O10/O17/O19/O22/O26</p><p>Quiet does not prove slow models; run end is not report delivery; billing ledgers are not QA. Compare undelivered, pending approval, finished-without-report and unknown states through fault tests. Relevant to FCoP handoff/receipt contracts, not automatic protocol-core scheduling requirements. Engagement: how to evidence guardrail/invocation races? No comments; zero reviews.</p><h2 id="dual-sources-dispositions-and-coverage-limits" tabindex="-1">Dual sources, dispositions and coverage limits <a class="header-anchor" href="#dual-sources-dispositions-and-coverage-limits" aria-label="Permalink to &quot;Dual sources, dispositions and coverage limits&quot;">​</a></h2><p>Fresh main Registry retains 47 researchers and 88 repositories with supplemental radar. People are subjects and repositories evidence, without relabeling related projects as official paper implementations. Commits/issues/releases queried per repository and saved locally. Commits limited to first 100, issues/releases to first ten; full pages/errors/unclassified records are not no-change and do not advance full baselines. Historical/classification gaps retained; this is a selected snapshot, not exhaustive coverage.</p><p>Separately read Cursor/MCP updates and Zhao&#39;s homepage: latest visible Cursor/MCP dates remain Nov 6/11, without a qualifying new announcement for this window. Not exhaustive across 47 people&#39;s X/papers. Marketing/QR/ordinary UI omitted; other candidates need detail review. TSA access failures and transient source timeouts retained separately. No competitor installation, upstream-test rerun, Registry/business-state edits or sent comments.</p><p><a href="https://cursor.com/changelog" target="_blank" rel="noreferrer">Cursor</a> · <a href="https://blog.modelcontextprotocol.io/" target="_blank" rel="noreferrer">MCP Blog</a> · <a href="https://yzhao062.github.io/index.html" target="_blank" rel="noreferrer">Yue Zhao</a></p><p>GitHub engineering evidence is distinct from official/author checks; two GitHub links are not two source types. Archive/deployment acceptance is recorded in run receipts. Untested CodeFlowMu/FCoP links remain research candidates.</p>',137)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
